def is_palindrome(s):
    if len(s) <= 1:
        return True
    if s[0] == s[-1]:
        return False
    return s[0] == s[-1]

def is_palindrome_dp(s):
    dp = [False] * (len(s) + 1)
    dp[0] = True
    for i in range(1, len(s) + 1):
        if s[i-1] == s[i]:
            dp[i] = dp[i-1]
        else:
            dp[i] = dp[i-1] or dp[i-2]
    return dp[len(s) - 1]
```

